import{_ as t,o as a,c as i,a2 as s}from"./chunks/framework.D66Xq0Kv.js";const g=JSON.parse('{"title":"Module 13 · Charity","description":"","frontmatter":{},"headers":[],"relativePath":"modules/13-charity.md","filePath":"modules/13-charity.md","lastUpdated":1790431304000}'),n={name:"modules/13-charity.md"};function o(r,e,d,l,h,p){return a(),i("div",null,[...e[0]||(e[0]=[s(`<h1 id="module-13-·-charity" tabindex="-1">Module 13 · Charity <a class="header-anchor" href="#module-13-·-charity" aria-label="Permalink to &quot;Module 13 · Charity&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Contract</strong></td><td><code>TownCharity.sol</code></td></tr><tr><td><strong>Stop</strong></td><td>Charity</td></tr><tr><td><strong>Pattern</strong></td><td>Milestone crowdfunding with pull refunds</td></tr><tr><td><strong>Stamp</strong></td><td>Module 13 (awarded to the <strong>donor</strong> on pledging)</td></tr></tbody></table><h2 id="the-problem" tabindex="-1">The problem <a class="header-anchor" href="#the-problem" aria-label="Permalink to &quot;The problem&quot;">​</a></h2><p>You give money to a cause. Then what?</p><p>Two failures dominate charitable giving, and they are different. <strong>The campaign does not reach its target</strong>, so the money is spent on a half-built well that helps nobody — the case Kickstarter&#39;s all-or-nothing rule exists to prevent. And <strong>the money arrives but the work does not</strong>, which no funding platform solves, because once the funds are released the donor&#39;s leverage is gone.</p><p>Traditional charity answers the second with audits, regulators and annual reports: slow, after the fact, and only as good as the auditor.</p><h2 id="the-idea" tabindex="-1">The idea <a class="header-anchor" href="#the-idea" aria-label="Permalink to &quot;The idea&quot;">​</a></h2><p>Two mechanisms stacked.</p><p><strong>All or nothing.</strong> Pledges sit in the contract. Reach the goal by the deadline or every donor takes their money back in full.</p><p><strong>Milestones.</strong> The goal is split into two to five stages, declared up front, each with a description and an amount. Money is released one stage at a time, and only after the beneficiary posts evidence and an arbiter approves it. Reject a milestone and the campaign is cancelled — donors get back their share of everything not yet released.</p><p>The donor&#39;s leverage survives past the funding date. That is the part traditional crowdfunding does not have.</p><h2 id="key-terms" tabindex="-1">Key terms <a class="header-anchor" href="#key-terms" aria-label="Permalink to &quot;Key terms&quot;">​</a></h2><p><strong>Milestone.</strong> A stage of work with a fixed amount attached. <code>Waiting → Submitted → Approved</code> or <code>Rejected</code>.</p><p><strong>Evidence hash.</strong> A <code>bytes32</code> — the hash of a report, photographs, receipts — anchored on chain while the documents stay off it. Same reasoning as modules 7 and 9.</p><p><strong>Pro-rata refund.</strong> When a campaign is cancelled mid-way, each donor gets back their share of what is <em>left</em>, not what they put in. Some money is already spent, and the loss is shared in proportion.</p><p><strong>Pull payment.</strong> Donors withdraw their own refunds. The contract never loops over a list of addresses paying them out — see module 6 for why.</p><h2 id="how-it-works" tabindex="-1">How it works <a class="header-anchor" href="#how-it-works" aria-label="Permalink to &quot;How it works&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Raising ──goal met──▸ Funded ──all milestones approved──▸ Completed</span></span>
<span class="line"><span>   │                    │</span></span>
<span class="line"><span>   └─deadline passed──▸ Failed          └─a milestone rejected──▸ Cancelled</span></span>
<span class="line"><span>       (full refunds)                        (pro-rata refunds)</span></span></code></pre></div><table tabindex="0"><thead><tr><th>Function</th><th>Who</th><th>What</th></tr></thead><tbody><tr><td><code>create(cause, goal, window, amounts[], what[])</code></td><td>anyone</td><td>Milestones must sum <strong>exactly</strong> to the goal</td></tr><tr><td><code>pledge(id, amount)</code></td><td>anyone</td><td>Capped at what is still needed</td></tr><tr><td><code>closeFailed(id)</code></td><td><strong>anyone</strong></td><td>After the deadline, under goal</td></tr><tr><td><code>submitEvidence(id, step, evidence)</code></td><td>the beneficiary</td><td>In order, one at a time</td></tr><tr><td><code>approveMilestone(id, step)</code></td><td><code>ARBITER_ROLE</code></td><td>Releases that amount</td></tr><tr><td><code>rejectMilestone(id, step, reason)</code></td><td><code>ARBITER_ROLE</code></td><td>Cancels the campaign</td></tr><tr><td><code>refund(id)</code></td><td>each donor</td><td>Failed or Cancelled only</td></tr><tr><td><code>refundable(id, donor)</code></td><td>view</td><td>What you can take, without sending a transaction</td></tr></tbody></table><p>Bounds: window 5 minutes to 90 days; 2 to 5 milestones.</p><p><strong>Milestones must sum to the goal, exactly:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (sum </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> goal) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> MilestonesDoNotSumToGoal</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sum, goal);</span></span></code></pre></div><p>No rounding, no slack, no leftover pot. If the arithmetic a donor checks is not the arithmetic the contract does, the contract is lying by omission.</p><h2 id="the-detail-that-matters" tabindex="-1">The detail that matters <a class="header-anchor" href="#the-detail-that-matters" aria-label="Permalink to &quot;The detail that matters&quot;">​</a></h2><p><strong>Pledges are capped at the remaining amount:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.goal </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.raised;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (amount </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> remaining) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Overfunded</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(remaining);</span></span></code></pre></div><p>This is a small rule with a large consequence: <code>raised</code> can never exceed <code>goal</code>, so <code>released</code> can never exceed what was pledged, so the pro-rata refund arithmetic cannot overflow its own pot. Overfunding is a genuine mess in practice — do you return the surplus, keep it, expand the project? — and the cleanest answer is to make it impossible.</p><p><strong>Anyone may close a failed campaign.</strong> Not the beneficiary:</p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">function</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> closeFailed</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#E36209;--shiki-dark:#FFAB70;"> id</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">external</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">block</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.timestamp </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.deadline) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">revert</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> TooEarly</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    c.state </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> State.Failed;</span></span></code></pre></div><p>A beneficiary whose campaign flopped has no incentive to announce it, and if closing were their decision the donors&#39; money would sit there indefinitely. Any donor, or any passer-by, can do it for the cost of gas. <strong>Never make an action that protects users depend on the party it protects them from.</strong></p><p><strong>The pro-rata refund:</strong></p><div class="language-solidity vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">solidity</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">uint256</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> owed </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.state </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">==</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> State.Failed</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    ?</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pledged</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">    :</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (pledged </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (c.raised </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.released)) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c.raised;</span></span></code></pre></div><p>Failed means nothing was released, so everyone is made whole. Cancelled means milestone one was paid and milestone two was rejected, so the remaining pot is shared in proportion to what each donor contributed. Integer division rounds down, leaving dust in the contract — tiny, deliberate, and worth understanding: rounding <em>against</em> the withdrawer is the only safe direction, because rounding the other way lets the last donor out with more than exists.</p><p><strong>The arbiter is the oracle, and this is the honest limitation.</strong> Someone must look at the evidence and decide whether the well was dug. The contract enforces the <em>process</em> — evidence before payment, one stage at a time, public rejection with a stated reason — and has no opinion on the <em>facts</em>. Module 14 attacks the same problem with a different tool, and does not solve it either.</p><p><strong>Evidence is a hash.</strong> The contract stores 32 bytes. A donor with the original report can prove it is the one submitted; a donor without it has 32 meaningless bytes. Anchoring proves integrity, never content.</p><h2 id="walk-through-it" tabindex="-1">Walk through it <a class="header-anchor" href="#walk-through-it" aria-label="Permalink to &quot;Walk through it&quot;">​</a></h2><ol><li>Create a campaign with a short window, a small goal, and three milestones summing to it.</li><li>From two other accounts, pledge — remember <code>approve</code> on TVD first.</li><li>Try to pledge more than remains. <code>Overfunded(remaining)</code> tells you the cap.</li><li>Reach the goal exactly. State flips to <code>Funded</code> in the same transaction.</li><li><strong>Beneficiary:</strong> submit evidence for milestone 1.</li><li>Try to submit for milestone 3. <code>WrongStep()</code> — stages are ordered.</li><li>Instructor approves milestone 1. That amount, and only that, reaches the beneficiary.</li><li>Submit milestone 2 and have it <strong>rejected</strong>. The campaign cancels.</li><li>Each donor calls <code>refundable</code>, then <code>refund</code>. Notice the amounts are smaller than the pledges, and work out why by hand before reading the code.</li></ol><p>Then the other path:</p><ol start="10"><li>A second campaign that never reaches its goal. After the deadline, <strong>a donor</strong> calls <code>closeFailed</code>, then everyone refunds in full.</li></ol><h2 id="what-actually-happened-on-chain" tabindex="-1">What actually happened on chain <a class="header-anchor" href="#what-actually-happened-on-chain" aria-label="Permalink to &quot;What actually happened on chain&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>CampaignCreated(id: 2, beneficiary: 0x…, goal: 300e18, deadline: 1790…, cause: &quot;new well&quot;)</span></span>
<span class="line"><span>Pledged(id: 2, donor: 0x…, amount: 200e18, raised: 200e18)</span></span>
<span class="line"><span>Pledged(id: 2, donor: 0x…, amount: 100e18, raised: 300e18)</span></span>
<span class="line"><span>GoalReached(id: 2, raised: 300e18)</span></span>
<span class="line"><span>EvidenceSubmitted(id: 2, step: 0, evidence: 0x…)</span></span>
<span class="line"><span>MilestoneApproved(id: 2, step: 0, amount: 100e18, arbiter: 0x…)</span></span>
<span class="line"><span>MilestoneRejected(id: 2, step: 1, reason: &quot;photographs show no work&quot;, arbiter: 0x…)</span></span>
<span class="line"><span>Refund(id: 2, donor: 0x…, amount: 133333333333333333333)</span></span></code></pre></div><p>Look at that last number: 133.333… TVD. Two hundred pledged, one third of the pot already released, two thirds of two hundred returned. The dust from the division stays in the contract for ever, and nothing in this design collects it — which is a reasonable choice and should be a conscious one.</p><h2 id="when-a-plain-database-is-better" tabindex="-1">When a plain database is better <a class="header-anchor" href="#when-a-plain-database-is-better" aria-label="Permalink to &quot;When a plain database is better&quot;">​</a></h2><p>For a registered charity in a functioning jurisdiction: the existing machinery is better. Gift aid, regulated accounts, a complaints process, and the ability to reverse a fraudulent card payment are not small things.</p><p>The milestone pattern earns its place when <strong>donors and beneficiary share no institution</strong> — cross-border giving, disaster response into somewhere with no functioning regulator, funding an anonymous developer — or when the point is that <strong>the process itself is auditable by anyone</strong>, not by an auditor everyone must trust.</p><p>Be honest about what it costs: no tax relief, no chargebacks, no help if the beneficiary&#39;s key is stolen, and an arbiter who is still just a person.</p><h2 id="what-this-does-not-fix" tabindex="-1">What this does not fix <a class="header-anchor" href="#what-this-does-not-fix" aria-label="Permalink to &quot;What this does not fix&quot;">​</a></h2><ul><li><strong>Whether the work was done.</strong> The arbiter decides; the contract enforces that they must decide in public.</li><li><strong>A captured arbiter.</strong> One role, one human. Collusion with the beneficiary defeats everything here.</li><li><strong>A dishonest beneficiary with plausible evidence.</strong> Photographs can be of someone else&#39;s well.</li><li><strong>Donor identity.</strong> Anyone can pledge, including the beneficiary, to fake momentum.</li><li><strong>The dust.</strong> Small, permanent, unclaimable.</li></ul><h2 id="common-mistakes" tabindex="-1">Common mistakes <a class="header-anchor" href="#common-mistakes" aria-label="Permalink to &quot;Common mistakes&quot;">​</a></h2><ul><li><strong>Releasing everything on funding.</strong> That is Kickstarter, and it is the problem.</li><li><strong>Pushing refunds in a loop.</strong> One reverting recipient freezes every donor&#39;s money.</li><li><strong>Letting the beneficiary declare failure.</strong> They never will.</li><li><strong>Milestones that do not sum to the goal.</strong> Either money is stranded or the last milestone cannot be paid.</li><li><strong>Rounding refunds up.</strong> The last donor out finds an empty pot.</li><li><strong>Forgetting <code>approve</code>.</strong> Every ERC-20 flow in this repository starts with it.</li><li><strong>Allowing overfunding, then improvising.</strong> Decide up front.</li></ul><h2 id="security-checklist" tabindex="-1">Security checklist <a class="header-anchor" href="#security-checklist" aria-label="Permalink to &quot;Security checklist&quot;">​</a></h2><ul><li>[ ] Can <code>raised</code> ever exceed <code>goal</code>?</li><li>[ ] Can a donor refund twice? Refund from a <code>Funded</code> campaign?</li><li>[ ] Does the sum of all refunds ever exceed <code>raised - released</code>?</li><li>[ ] Can the beneficiary skip a milestone, or resubmit an approved one?</li><li>[ ] Can a campaign be closed as failed before its deadline?</li><li>[ ] Can the arbiter release money to anyone but the beneficiary?</li><li>[ ] What happens if the arbiter never rules — is the money stuck for ever?</li></ul><h2 id="extend-it" tabindex="-1">Extend it <a class="header-anchor" href="#extend-it" aria-label="Permalink to &quot;Extend it&quot;">​</a></h2><ol><li>Replace the single arbiter with the module 11 multisig, then with the module 12 DAO. Time both, and decide what a donor would actually prefer.</li><li>Add a donor veto: if holders of more than half the pledges object within a window, the milestone is rejected without an arbiter. Then work out how a whale abuses that.</li><li>Add a deadline per milestone, so a silent beneficiary cannot leave funds locked for ever. Decide where the money goes when it expires.</li><li>Let donors delegate their vote on milestones to someone who will actually read the evidence. You have just rebuilt module 12 for a narrower purpose.</li></ol><h2 id="further-reading" tabindex="-1">Further reading <a class="header-anchor" href="#further-reading" aria-label="Permalink to &quot;Further reading&quot;">​</a></h2><ul><li><a href="https://docs.openzeppelin.com/contracts/5.x/access-control" target="_blank" rel="noreferrer">OpenZeppelin AccessControl</a></li><li><a href="https://docs.soliditylang.org/en/latest/common-patterns.html#withdrawal-from-contracts" target="_blank" rel="noreferrer">Pull over push payments</a></li><li>Read about assurance contracts and dominant-assurance contracts — the economics behind all-or-nothing funding, and older than any of this.</li></ul><p><strong>Next:</strong> <a href="./14-insurer">Module 14 · Insurer and oracle →</a></p>`,57)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
